+export interface Notifier {
+  send(userId: string, message: string): Promise<void>;
+}
+
+export class EmailNotifier implements Notifier {
+  async send(userId: string, message: string): Promise<void> {
+    await postJson("/internal/email", { userId, message });
+  }
+}
+
+export class SmsNotifier implements Notifier {
+  async send(userId: string, message: string): Promise<void> {
+    await postJson("/internal/sms", { userId, message });
+  }
+}
+
+export function notifierFor(pref: "email" | "sms"): Notifier {
+  return pref === "email" ? new EmailNotifier() : new SmsNotifier();
+}
+
+export async function remindUser(
+  userId: string,
+  pref: "email" | "sms",
+  phone: string | null,
+): Promise<void> {
+  if (pref === "sms" && phone === null) {
+    throw new Error(`user ${userId} has no phone number on file`);
+  }
+  await notifierFor(pref).send(userId, "Your report is ready.");
+}
+
+async function postJson(path: string, body: unknown): Promise<void> {
+  await fetch(path, { method: "POST", body: JSON.stringify(body) });
+}
